select c.discrepancy_case_id, c.receipt_id, c.receipt_allocation_id, c.shipment_id, c.transfer_id, c.shipment_allocation_id, ra.shipment_detail_id, ra.transfer_detail_id, coalesce(nullif(o.from_warehouse_id, 0), o.from_dept_id) as source_dept_id, coalesce(nullif(o.to_warehouse_id, 0), o.to_dept_id) as target_dept_id, o.from_dept_name as source_name, o.to_dept_name as target_name, o.order_no, s.shipment_no, r.receipt_no, r.receipt_plan_version, ra.item_type, ra.item_id, sd.item_code, sd.item_name, td.unit, c.discrepancy_type, c.discrepancy_quantity, c.source_cost_price, c.discrepancy_amount, c.fact_fingerprint, c.discrepancy_note, c.attachment_refs, c.status as case_status, c.case_version, c.create_by as case_create_by, c.create_time as case_create_time, source_event.confirmation_event_id as source_event_id, source_event.request_id as source_request_id, source_event.case_version as source_case_version, source_event.fact_fingerprint as source_fact_fingerprint, source_event.party_role as source_party_role, source_event.party_dept_id as source_party_dept_id, source_event.decision as source_decision, source_event.confirmation_note as source_note, source_event.operator_user_id as source_operator_user_id, source_event.operator_name as source_operator_name, source_event.create_time as source_create_time, target_event.confirmation_event_id as target_event_id, target_event.request_id as target_request_id, target_event.case_version as target_case_version, target_event.fact_fingerprint as target_fact_fingerprint, target_event.party_role as target_party_role, target_event.party_dept_id as target_party_dept_id, target_event.decision as target_decision, target_event.confirmation_note as target_note, target_event.operator_user_id as target_operator_user_id, target_event.operator_name as target_operator_name, target_event.create_time as target_create_time from inv_transfer_receipt_discrepancy_case c inner join inv_transfer_shipment_receipt_allocation ra on ra.receipt_allocation_id = c.receipt_allocation_id and ra.receipt_id = c.receipt_id and ra.shipment_id = c.shipment_id and ra.shipment_allocation_id = c.shipment_allocation_id inner join inv_transfer_shipment_receipt r on r.receipt_id = c.receipt_id and r.shipment_id = c.shipment_id and r.transfer_id = c.transfer_id inner join inv_transfer_shipment_allocation allocation on allocation.allocation_id = c.shipment_allocation_id and allocation.shipment_id = c.shipment_id and allocation.shipment_detail_id = ra.shipment_detail_id and allocation.transfer_detail_id = ra.transfer_detail_id and allocation.transfer_id = c.transfer_id inner join inv_transfer_shipment_detail sd on sd.shipment_detail_id = ra.shipment_detail_id and sd.shipment_id = c.shipment_id and sd.transfer_id = c.transfer_id and sd.transfer_detail_id = ra.transfer_detail_id and sd.item_type = ra.item_type and sd.item_id = ra.item_id inner join inv_transfer_shipment s on s.shipment_id = c.shipment_id and s.transfer_id = c.transfer_id and s.inventory_write_version = 'V2_DETAIL' inner join inv_transfer_detail td on td.detail_id = ra.transfer_detail_id and td.transfer_id = c.transfer_id inner join inv_transfer_order o on o.transfer_id = c.transfer_id left join inv_transfer_receipt_discrepancy_confirmation_event source_event on source_event.confirmation_event_id = ( select max(source_latest.confirmation_event_id) from inv_transfer_receipt_discrepancy_confirmation_event source_latest where source_latest.discrepancy_case_id = c.discrepancy_case_id and source_latest.party_role = 'source' ) left join inv_transfer_receipt_discrepancy_confirmation_event target_event on target_event.confirmation_event_id = ( select max(target_latest.confirmation_event_id) from inv_transfer_receipt_discrepancy_confirmation_event target_latest where target_latest.discrepancy_case_id = c.discrepancy_case_id and target_latest.party_role = 'target' ) where c.discrepancy_case_id = #{caseId} and c.discrepancy_type in ('damaged', 'shortage') and c.discrepancy_quantity > 0 and c.discrepancy_quantity = case when c.discrepancy_type = 'damaged' then ra.damaged_quantity else ra.shortage_quantity end and c.source_cost_price = ra.cost_price and c.discrepancy_amount = round( c.source_cost_price * c.discrepancy_quantity, 6) and c.discrepancy_note = ra.discrepancy_note and c.attachment_refs = ra.attachment_refs
and ( coalesce(nullif(o.from_warehouse_id, 0), o.from_dept_id) in
#{scopeDeptId}
or coalesce(nullif(o.to_warehouse_id, 0), o.to_dept_id) in
#{scopeDeptId}
)
for update

