update inv_transfer_receipt_discrepancy_case
set status = 'adjudication_planned',
    case_version = #{adjudication.caseVersionAfter}
where discrepancy_case_id = #{adjudication.caseId}
  and case_version = #{adjudication.caseVersionBefore}
  and fact_fingerprint = #{adjudication.factFingerprint}
  and status = 'awaiting_confirmation'
  and exists (
      select 1
      from inv_transfer_receipt_discrepancy_adjudication persisted
      where persisted.request_id = #{adjudication.requestId}
        and persisted.discrepancy_case_id =
            #{adjudication.caseId}
        and persisted.case_version_before =
            #{adjudication.caseVersionBefore}
        and persisted.case_version_after =
            #{adjudication.caseVersionAfter}
        and persisted.decision_fingerprint =
            #{adjudication.decisionFingerprint}
        and persisted.plan_status = 'adjudication_planned'
  )
